package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/rbac-admin-api/internal/authz"
	"github.com/luwa07832/rbac-admin-api/internal/store"
)

// NewRouter wires the public HTTP surface. The service contract in README.md
// describes the error shape every entry must keep.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	// Identifiers may contain "/" (e.g. "tenant-a/doc-1"); keep %2F encoded
	// inside a single path parameter instead of splitting the route.
	router.UseRawPath = true
	router.UnescapePathValues = false
	router.Use(gin.Recovery())

	service := authz.NewService(st)

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	registerCatalog(router, service, "subjects", store.CatalogSubject)
	registerCatalog(router, service, "resources", store.CatalogResource)
	registerCatalog(router, service, "operations", store.CatalogOperation)
	registerCatalog(router, service, "roles", store.CatalogRole)
	registerCatalog(router, service, "permissions", store.CatalogPermission)

	router.PUT("/roles/:id/parents", setRoleParentsHandler(service))
	router.PUT("/permissions/:id/operations", setPermissionOperationsHandler(service))

	router.PUT("/subjects/:id/bindings/:role", grantBindingHandler(service))
	router.PATCH("/subjects/:id/bindings/:role", updateBindingHandler(service))
	router.DELETE("/subjects/:id/bindings/:role", revokeBindingHandler(service))

	router.PUT("/roles/:id/permissions/:perm", grantRolePermissionHandler(service))
	router.PATCH("/roles/:id/permissions/:perm", updateRolePermissionHandler(service))
	router.DELETE("/roles/:id/permissions/:perm", revokeRolePermissionHandler(service))

	router.PUT("/subjects/:id/scopes", grantScopeHandler(service))
	router.PATCH("/subjects/:id/scopes", updateScopeHandler(service))
	router.DELETE("/subjects/:id/scopes", revokeScopeHandler(service))

	router.POST("/authorize", authorizeHandler(service))
	router.POST("/authorize/batch", authorizeBatchHandler(service))
	router.POST("/authorize/explain", authorizeExplainHandler(service))
	router.GET("/history", historyHandler(service))
	router.GET("/subjects/:id/access", accessHandler(service))
	router.GET("/subjects/:id/access/diff", accessDiffHandler(service))
	router.GET("/roles/:role/permissions", rolePermissionsHandler(service))
	router.GET("/resources/:resource/subjects", resourceSubjectsHandler(service))
	router.GET("/resources/:resource/subjects/diff", resourceSubjectsDiffHandler(service))

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

func registerCatalog(router *gin.Engine, service *authz.Service, segment string, kind store.CatalogKind) {
	router.PUT("/"+segment+"/:id", func(c *gin.Context) {
		if fail := service.Register(authz.RegisterInput{Kind: kind, ID: pathParam(c, "id")}); fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, gin.H{"registered": true})
	})
}
package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/rbac-admin-api/internal/authz"
)

type authorizeRequestBody struct {
	Subject     string `json:"subject"`
	Resource    string `json:"resource"`
	Operation   string `json:"operation"`
	EffectiveAt string `json:"effectiveAt"`
}

func authorizeHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		var body authorizeRequestBody
		if fail := readJSON(c, &body, false); fail != nil {
			writeFailure(c, fail)
			return
		}
		decision, fail := service.Decide(authz.DecisionInput{
			Subject:     body.Subject,
			Resource:    body.Resource,
			Operation:   body.Operation,
			EffectiveAt: body.EffectiveAt,
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, gin.H{"decision": decisionResponse(decision)})
	}
}

func authorizeExplainHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		var body authorizeRequestBody
		if fail := readJSON(c, &body, false); fail != nil {
			writeFailure(c, fail)
			return
		}
		view, fail := service.Explain(authz.DecisionInput{
			Subject:     body.Subject,
			Resource:    body.Resource,
			Operation:   body.Operation,
			EffectiveAt: body.EffectiveAt,
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, gin.H{
			"effectiveAt": view.EffectiveAt,
			"decision":    decisionResponse(view.Decision),
			"paths":       view.Paths,
		})
	}
}

func decisionResponse(decision *authz.Decision) gin.H {
	if decision.Granted {
		return gin.H{
			"granted":           true,
			"matchedRole":       nullableJSON(decision.Match.Role),
			"matchedPermission": nullableJSON(decision.Match.Permission),
			"matchedScope":      decision.Match.Scope,
		}
	}
	return gin.H{"granted": false, "reason": decision.Reason}
}

func nullableJSON(value string) any {
	if value == "" {
		return nil
	}
	return value
}

func accessHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		items, fail := service.Access(authz.AccessInput{
			Subject:     pathParam(c, "id"),
			EffectiveAt: c.Query("effectiveAt"),
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, gin.H{"access": items})
	}
}

func accessDiffHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		view, fail := service.AccessDiff(authz.AccessDiffInput{
			Subject: pathParam(c, "id"),
			From:    c.Query("from"),
			To:      c.Query("to"),
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, view)
	}
}

func rolePermissionsHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		view, fail := service.RolePermissions(authz.RolePermissionsInput{
			Role:        pathParam(c, "role"),
			EffectiveAt: c.Query("effectiveAt"),
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, view)
	}
}

func resourceSubjectsHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		view, fail := service.ResourceSubjects(authz.ResourceSubjectsInput{
			Resource:    pathParam(c, "resource"),
			Operation:   c.Query("operation"),
			EffectiveAt: c.Query("effectiveAt"),
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, view)
	}
}

func resourceSubjectsDiffHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		view, fail := service.ResourceSubjectsDiff(authz.ResourceSubjectsDiffInput{
			Resource:  pathParam(c, "resource"),
			Operation: c.Query("operation"),
			From:      c.Query("from"),
			To:        c.Query("to"),
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, view)
	}
}

func historyHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		subject := c.Query("subject")
		resource := c.Query("resource")
		operation := c.Query("operation")
		if subject == "" || resource == "" || operation == "" {
			writeFailure(c, &authz.Failure{
				Type:    authz.TypeInvalidRequest,
				Field:   "subject",
				Message: "subject, resource and operation query parameters are required",
			})
			return
		}
		events, fail := service.History(authz.HistoryInput{
			Subject:   subject,
			Resource:  resource,
			Operation: operation,
			From:      c.Query("from"),
			To:        c.Query("to"),
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, gin.H{"events": events})
	}
}
package api

import (
	"bytes"
	"encoding/json"
	"io"
	"net/http"
	"sort"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/rbac-admin-api/internal/authz"
)

// maxBatchQueries mirrors authz.MaxBatchQueries at the structural validation
// layer; the service enforces the same bound for direct callers.
const maxBatchQueries = authz.MaxBatchQueries

type batchDecisionItem struct {
	Subject   string `json:"subject"`
	Resource  string `json:"resource"`
	Operation string `json:"operation"`
	Decision  gin.H  `json:"decision"`
}

// authorizeBatchHandler serves POST /authorize/batch. The whole structure and
// shared effectiveAt are validated before any per-query check, and any failure
// returns one error object without partial decisions.
func authorizeBatchHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		effectiveAt, queries, fail := readBatchRequest(c)
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		results, fail := service.BatchDecide(authz.BatchInput{
			EffectiveAtText: effectiveAt,
			Queries:         queries,
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		decisions := make([]batchDecisionItem, len(results))
		for index, result := range results {
			decisions[index] = batchDecisionItem{
				Subject:   result.Subject,
				Resource:  result.Resource,
				Operation: result.Operation,
				Decision:  decisionResponse(result.Decision),
			}
		}
		c.JSON(http.StatusOK, gin.H{"decisions": decisions})
	}
}

// readBatchRequest performs the batch-level checks: the body must be one JSON
// object with only effectiveAt and queries, queries must be a non-empty array
// of at most 100 entries, and an effectiveAt that is present and non-null
// must be a string. An invalid effectiveAt string outranks every per-query
// check and is reported as INVALID_TIME by the service.
func readBatchRequest(c *gin.Context) (*string, []json.RawMessage, *authz.Failure) {
	c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, 1<<20)
	raw, err := io.ReadAll(c.Request.Body)
	if err != nil {
		return nil, nil, &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is missing or too large"}
	}

	var fields map[string]json.RawMessage
	if err := json.Unmarshal(bytes.TrimSpace(raw), &fields); err != nil {
		return nil, nil, &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is not valid JSON for this entry"}
	}
	if fields == nil {
		return nil, nil, &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body must be a JSON object"}
	}

	names := make([]string, 0, len(fields))
	for name := range fields {
		if name != "effectiveAt" && name != "queries" {
			names = append(names, name)
		}
	}
	if len(names) > 0 {
		sort.Strings(names)
		return nil, nil, &authz.Failure{Type: authz.TypeInvalidRequest, Field: names[0], Message: "unknown field " + names[0]}
	}

	rawQueries, present := fields["queries"]
	if !present {
		return nil, nil, &authz.Failure{Type: authz.TypeInvalidRequest, Field: "queries", Message: "field queries is required"}
	}
	var queries []json.RawMessage
	if err := json.Unmarshal(rawQueries, &queries); err != nil {
		return nil, nil, &authz.Failure{Type: authz.TypeInvalidRequest, Field: "queries", Message: "field queries must be an array"}
	}
	if len(queries) == 0 {
		return nil, nil, &authz.Failure{Type: authz.TypeInvalidRequest, Field: "queries", Message: "field queries must contain at least one entry"}
	}
	if len(queries) > maxBatchQueries {
		return nil, nil, &authz.Failure{Type: authz.TypeInvalidRequest, Field: "queries", Message: "field queries must contain at most 100 entries"}
	}

	var effectiveAt *string
	if rawEffectiveAt, ok := fields["effectiveAt"]; ok {
		if string(bytes.TrimSpace(rawEffectiveAt)) != "null" {
			var text string
			if err := json.Unmarshal(rawEffectiveAt, &text); err != nil {
				return nil, nil, &authz.Failure{Type: authz.TypeInvalidTime, Field: "effectiveAt", Message: "time must be an RFC3339 timestamp"}
			}
			effectiveAt = &text
		}
	}
	return effectiveAt, queries, nil
}
package api

import "net/url"

// pathParam returns a raw path parameter. With UseRawPath enabled, percent
// sequences such as %2F stay encoded, so identifiers containing "/" survive
// inside a single parameter and are decoded here.
func pathParam(c interface{ Param(string) string }, name string) string {
	value := c.Param(name)
	if decoded, err := url.PathUnescape(value); err == nil {
		return decoded
	}
	return value
}
package api

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/rbac-admin-api/internal/authz"
)

// readJSON reads a JSON object body with strict unknown-field and type
// checking. An empty body is allowed when optional is true (timing-only writes
// default every field to its zero value).
func readJSON(c *gin.Context, target any, optional bool) *authz.Failure {
	c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, 1<<20)
	raw, err := io.ReadAll(c.Request.Body)
	if err != nil {
		return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is missing or too large"}
	}
	trimmed := strings.TrimSpace(string(raw))
	if trimmed == "" {
		if optional {
			return nil
		}
		return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is empty"}
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(target); err != nil {
		if _, ok := err.(*json.UnmarshalTypeError); ok {
			return &authz.Failure{Type: authz.TypeInvalidRequest, Message: fmt.Sprintf("request body field has the wrong type: %v", err)}
		}
		return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body is not valid JSON for this entry"}
	}
	if decoder.More() {
		return &authz.Failure{Type: authz.TypeInvalidRequest, Message: "request body contains more than one JSON value"}
	}
	return nil
}

func writeFailure(c *gin.Context, fail *authz.Failure) {
	if fail == nil {
		return
	}
	status := http.StatusBadRequest
	switch fail.Type {
	case authz.TypeNotFound:
		status = http.StatusNotFound
	case authz.TypeConflict:
		status = http.StatusConflict
	}
	errorObject := gin.H{"type": fail.Type, "message": fail.Message}
	if fail.Field != "" {
		errorObject["field"] = fail.Field
	}
	c.JSON(status, gin.H{"error": errorObject})
}

