	narrowed := authorize(h, map[string]any{"subject": "user-1", "resource": "tenant-b/doc-2", "operation": "read", "effectiveAt": "2026-09-01T00:00:00Z"})
	if narrowed["granted"] != false || narrowed["reason"] != "OUT_OF_SCOPE" {
