package api

import (
	"encoding/json"
	"fmt"
	"net/http"
	"reflect"
	"strings"
	"testing"
)

type batchExplainEnvelope struct {
	EffectiveAt  string             `json:"effectiveAt"`
	Explanations []batchExplainItem `json:"explanations"`
}

func batchExplainRaw(h *apiHarness, body string) *batchExplainEnvelope {
	h.t.Helper()
	recorder := h.raw(http.MethodPost, "/authorize/batch/explain", body)
	if recorder.Code != http.StatusOK {
		h.t.Fatalf("status = %d body = %s, want %d", recorder.Code, recorder.Body.String(), http.StatusOK)
	}
	var envelope batchExplainEnvelope
	if err := json.Unmarshal(recorder.Body.Bytes(), &envelope); err != nil {
		h.t.Fatalf("decode %q: %v", recorder.Body.String(), err)
	}
	return &envelope
}

func batchExplainError(t *testing.T, h *apiHarness, body string, wantStatus int, wantType, wantField string) {
	t.Helper()
	recorder := h.raw(http.MethodPost, "/authorize/batch/explain", body)
	if recorder.Code != wantStatus {
		t.Fatalf("status = %d body = %s, want %d", recorder.Code, recorder.Body.String(), wantStatus)
	}
	parsed := mustJSON(t, recorder)
	errorObject := parsed["error"].(map[string]any)
	field, _ := errorObject["field"].(string)
	if errorObject["type"] != wantType || field != wantField {
		t.Fatalf("error = %v, want type %s field %s", errorObject, wantType, wantField)
	}
	if _, ok := parsed["explanations"]; ok {
		t.Fatalf("error response leaked explanations: %s", recorder.Body.String())
	}
}

func TestAuthorizeBatchExplainGrantedAndDenied(t *testing.T) {
	h := newHarness(t)
	seedBatchBaseline(h)

	envelope := batchExplainRaw(h, `{
		"effectiveAt":"2026-02-01T00:00:00Z",
		"queries":[
			{"subject":"user-1","resource":"tenant-a/doc-1","operation":"read"},
			{"subject":"user-2","resource":"tenant-a/doc-1","operation":"read"},
			{"subject":"user-1","resource":"tenant-a/doc-1","operation":"audit"},
			{"subject":"user-1","resource":"tenant-b/doc-2","operation":"write"},
			{"subject":"user-1","resource":"tenant-b/doc-2","operation":"read"}
		]}`)
	if envelope.EffectiveAt != "2026-02-01T00:00:00Z" {
		t.Fatalf("effectiveAt = %q", envelope.EffectiveAt)
	}
	if len(envelope.Explanations) != 5 {
		t.Fatalf("explanations = %s", recorderEnvelope(envelope))
	}

	first := envelope.Explanations[0]
	if first.Subject != "user-1" || first.Resource != "tenant-a/doc-1" || first.Operation != "read" {
		t.Fatalf("first echo = %+v", first)
	}
	if decision := first.Decision; decision["granted"] != true ||
		decision["matchedRole"] != nil || decision["matchedPermission"] != "doc-read" ||
		decision["matchedScope"] != "tenant-a/doc-1" {
		t.Fatalf("first decision = %v", first.Decision)
	}
	wantPaths := []map[string]any{
		wantPath("DIRECT_PERMISSION", nil, nil, "doc-read", "tenant-a/doc-1"),
		wantPath("ROLE", "viewer", "base", "doc-read", "tenant-a/*"),
	}
	if got := pathsAsAny(first.Paths); !reflect.DeepEqual(got, wantPaths) {
		t.Fatalf("first paths = %v, want %v", got, wantPaths)
	}

	denied := []struct {
		index        int
		reason       string
		subject      string
		resource     string
		operation    string
	}{
		{1, "NO_ROLE_BINDING", "user-2", "tenant-a/doc-1", "read"},
		{2, "NO_PERMISSION_BINDING", "user-1", "tenant-a/doc-1", "audit"},
		{3, "OUT_OF_SCOPE", "user-1", "tenant-b/doc-2", "write"},
		{4, "OUT_OF_SCOPE", "user-1", "tenant-b/doc-2", "read"},
	}
	for _, item := range denied {
		explanation := envelope.Explanations[item.index]
		if explanation.Subject != item.subject || explanation.Resource != item.resource ||
			explanation.Operation != item.operation {
			t.Fatalf("[%d] echo = %+v", item.index, explanation)
		}
		if decision := explanation.Decision; decision["granted"] != false ||
			decision["reason"] != item.reason || len(decision) != 2 {
			t.Fatalf("[%d] decision = %v, want %s", item.index, decision, item.reason)
		}
		if len(explanation.Paths) != 0 {
			t.Fatalf("[%d] denied paths must be empty: %v", item.index, explanation.Paths)
		}
	}
}

func TestAuthorizeBatchExplainDenialReasons(t *testing.T) {
	h := newHarness(t)
	seedBaseline(h)

	queries := func() string {
		return `[
			{"subject":"user-1","resource":"tenant-a/doc-1","operation":"read"}
		]`
	}

	envelope := batchExplainRaw(h, `{"effectiveAt":"2026-02-01T00:00:00Z","queries":`+queries()+`}`)
	if reason := envelope.Explanations[0].Decision["reason"]; reason != "NO_ROLE_BINDING" {
		t.Fatalf("reason = %v", reason)
	}

	h.mustStatus(h.request(http.MethodPut, "/subjects/user-1/bindings/viewer",
		map[string]any{"effectiveFrom": "2026-01-01T00:00:00Z"}), http.StatusOK)
	envelope = batchExplainRaw(h, `{"effectiveAt":"2026-02-01T00:00:00Z","queries":`+queries()+`}`)
	if reason := envelope.Explanations[0].Decision["reason"]; reason != "NO_PERMISSION_BINDING" {
		t.Fatalf("reason = %v", reason)
	}

	h.mustStatus(h.request(http.MethodPut, "/roles/viewer/permissions/doc-read",
		map[string]any{"effectiveFrom": "2026-01-01T00:00:00Z"}), http.StatusOK)
	envelope = batchExplainRaw(h, `{"effectiveAt":"2026-02-01T00:00:00Z","queries":`+queries()+`}`)
	if reason := envelope.Explanations[0].Decision["reason"]; reason != "OUT_OF_SCOPE" {
		t.Fatalf("reason = %v", reason)
	}

	h.mustStatus(h.request(http.MethodDelete, "/subjects/user-1/bindings/viewer",
		map[string]any{"effectiveFrom": "2026-01-15T00:00:00Z"}), http.StatusOK)
	envelope = batchExplainRaw(h, `{"effectiveAt":"2026-02-01T00:00:00Z","queries":`+queries()+`}`)
	if reason := envelope.Explanations[0].Decision["reason"]; reason != "NOT_EFFECTIVE" {
		t.Fatalf("reason = %v", reason)
	}
}

func TestAuthorizeBatchExplainMatchesSingleExplainAndKeepsDuplicates(t *testing.T) {
	h := newHarness(t)
	seedSubjectGraph(h)

	triples := []struct{ subject, resource, operation string }{
		{"user-1", "tenant-a/doc-1", "read"},
		{"user-2", "tenant-a/doc-1", "read"},
		{"user-1", "tenant-b/doc-2", "read"},
		{"user-1", "tenant-a/doc-1", "read"},
	}
	rawQueries := ""
	for index, query := range triples {
		if index > 0 {
			rawQueries += ","
		}
		rawQueries += fmt.Sprintf(`{"subject":%q,"resource":%q,"operation":%q}`,
			query.subject, query.resource, query.operation)
	}
	envelope := batchExplainRaw(h, `{"effectiveAt":"2026-02-01T00:00:00Z","queries":[`+rawQueries+`]}`)
	if len(envelope.Explanations) != len(triples) {
		t.Fatalf("explanations = %s", recorderEnvelope(envelope))
	}
	for index, query := range triples {
		explanation := envelope.Explanations[index]
		single := explain(h, map[string]any{
			"subject": query.subject, "resource": query.resource, "operation": query.operation,
			"effectiveAt": "2026-02-01T00:00:00Z",
		})
		if explanation.Subject != query.subject || explanation.Resource != query.resource ||
			explanation.Operation != query.operation {
			t.Fatalf("[%d] echo = %+v", index, explanation)
		}
		if fmt.Sprint(explanation.Decision) != fmt.Sprint(single["decision"]) {
			t.Fatalf("[%d] decision %v != single %v", index, explanation.Decision, single["decision"])
		}
		if got := pathsAsAny(explanation.Paths); !reflect.DeepEqual(got, single["paths"]) {
			t.Fatalf("[%d] paths %v != single %v", index, got, single["paths"])
		}
	}
	// Duplicate triples stay separate, in input order, with identical content.
	first := envelope.Explanations[0]
	dup := envelope.Explanations[3]
	if fmt.Sprint(first.Decision) != fmt.Sprint(dup.Decision) ||
		fmt.Sprint(first.Paths) != fmt.Sprint(dup.Paths) {
		t.Fatalf("duplicate explanations diverged: %+v vs %+v", first, dup)
	}
}

func TestAuthorizeBatchExplainDeduplicatesOverlappingVersions(t *testing.T) {
	h := newHarness(t)
	seedBaseline(h)
	grantAt(h, "/subjects/user-1/bindings/viewer", nil)
	grantAt(h, "/roles/viewer/permissions/doc-read", nil)
	grantAt(h, "/subjects/user-1/scopes", map[string]any{"role": "viewer", "scope": "tenant-a/*"})

	// Two binding versions overlap at the queried moment; the path appears once.
	h.mustStatus(h.request(http.MethodDelete, "/subjects/user-1/bindings/viewer",
		map[string]any{"effectiveFrom": "2026-06-01T00:00:00Z"}), http.StatusOK)
	h.mustStatus(h.request(http.MethodPut, "/subjects/user-1/bindings/viewer",
		map[string]any{"effectiveFrom": "2026-03-01T00:00:00Z"}), http.StatusOK)

	envelope := batchExplainRaw(h, `{"effectiveAt":"2026-04-01T00:00:00Z","queries":[
		{"subject":"user-1","resource":"tenant-a/doc-1","operation":"read"}]}`)
	wantPaths := []map[string]any{
