		t.Fatalf("history changed: %v -> %v", eventsBefore, eventsAfter)
	}
	again := batchExplain(h, map[string]any{
		"queries": []any{
			map[string]any{"subject": "user-1", "resource": "tenant-a/doc-1", "operation": "read"},
		},
	})
	if !reflect.DeepEqual(again, view) {
