	}

	// An explicit null effectiveAt is treated as omitted.
	view = batchExplain(h, map[string]any{
		"effectiveAt": nil,
		"queries":     []any{map[string]any{"subject": "user-1", "resource": "tenant-a/doc-1", "operation": "read"}},
	})
